{
  "schema_version": "1.0",
  "variables": {
    "title": "Why Cutline replaced our entire render farm",
    "author": "u/DevEngineer",
    "fps": 60
  },
  "outputs": [
    {
      "id": "tt",
      "aspect": "9:16",
      "resolution": {
        "width": 1080,
        "height": 1920
      },
      "fps": 60,
      "format": "mp4",
      "codec": "h264",
      "reframe": "smart"
    },
    {
      "id": "sq",
      "aspect": "1:1",
      "resolution": {
        "width": 1080,
        "height": 1080
      },
      "fps": 60,
      "format": "mp4",
      "codec": "h264",
      "reframe": "smart"
    },
    {
      "id": "yt",
      "aspect": "16:9",
      "resolution": {
        "width": 1920,
        "height": 1080
      },
      "fps": 60,
      "format": "mp4",
      "codec": "h264",
      "reframe": "smart"
    }
  ],
  "assets": {
    "bg": {
      "type": "video",
      "src": "https://assets.cutline.dev/demo/background_loop.mp4",
      "duration": 15.0,
      "loop": true
    },
    "vo": {
      "type": "audio",
      "src": "https://assets.cutline.dev/demo/voiceover.wav",
      "duration": 10.0
    },
    "music": {
      "type": "audio",
      "src": "https://assets.cutline.dev/demo/ambient_bed.mp3",
      "duration": 15.0,
      "loop": true
    }
  },
  "tracks": [
    {
      "id": "v1",
      "kind": "video",
      "clips": [
        {
          "id": "clip_bg",
          "asset": "bg",
          "start": 0,
          "duration": {
            "Seconds": 10.0
          },
          "fit": "cover"
        }
      ]
    },
    {
      "id": "t1",
      "kind": "text",
      "clips": [
        {
          "id": "clip_title",
          "text": "{{title}}",
          "font": "Inter",
          "size": 42.0,
          "color": "#FFFFFF",
          "align": "center",
          "start": 0,
          "duration": {
            "Seconds": 10.0
          }
        }
      ]
    },
    {
      "id": "a1",
      "kind": "audio",
      "clips": [
        {
          "id": "clip_vo",
          "asset": "vo",
          "start": 0,
          "duration": {
            "Seconds": 10.0
          }
        }
      ],
      "mix": {
        "role": "voice"
      }
    },
    {
      "id": "a2",
      "kind": "audio",
      "clips": [
        {
          "id": "clip_music",
          "asset": "music",
          "start": 0,
          "duration": {
            "Seconds": 10.0
          }
        }
      ],
      "mix": {
        "role": "music",
        "volume_db": -6.0
      }
    }
  ],
  "audio": {
    "normalize_lufs": -14.0,
    "duck": {
      "under": "voice",
      "amount_db": -18.0
    }
  }
}

